WITH recent_transactions AS (SELECT * FROM transactions WHERE is_flagged), agg AS (SELECT DATE_TRUNC('MONTH', txn_time) AS txn_month, ROUND((100 * SUM(CASE WHEN txn_type = 'REFUND' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_refund, SUM(CASE WHEN merchant = 'Grab' THEN 1 ELSE 0 END) AS grab_count FROM recent_transactions GROUP BY DATE_TRUNC('MONTH', txn_time)) SELECT txn_month, pct_refund FROM agg WHERE pct_refund > 58;
